    NotifFrame.BorderSizePixel = 0
    NotifFrame.Parent = ScreenGui

    local NotifCorner = Instance.new("UICorner")
    NotifCorner.CornerRadius = UDim.new(0, 8)
    NotifCorner.Parent = NotifFrame

    local NotifStroke = Instance.new("UIStroke")
    NotifStroke.Color = Color3.fromRGB(50, 140, 255)
    NotifStroke.Thickness = 1
    NotifStroke.Parent = NotifFrame

    local NotifIcon = Instance.new("ImageLabel")
    NotifIcon.Size = UDim2.new(0, 36, 0, 36)
    NotifIcon.Position = UDim2.new(0, 12, 0.5, -18)
    NotifIcon.BackgroundTransparency = 1
    NotifIcon.Image = "rbxassetid://91099679470963"
    NotifIcon.Parent = NotifFrame

    local NIconCorner = Instance.new("UICorner")
    NIconCorner.CornerRadius = UDim.new(1, 0)
    NIconCorner.Parent = NotifIcon

    local NotifTitle = Instance.new("TextLabel")
    NotifTitle.Size = UDim2.new(0, 180, 0, 18)
    NotifTitle.Position = UDim2.new(0, 58, 0, 12)
    NotifTitle.BackgroundTransparency = 1
    NotifTitle.Text = titleText
    NotifTitle.TextColor3 = Color3.fromRGB(255, 255, 255)
    NotifTitle.Font = Enum.Font.GothamBold
    NotifTitle.TextSize = 12
    NotifTitle.TextXAlignment = Enum.TextXAlignment.Left
    NotifTitle.Parent = NotifFrame

    local NotifDesc = Instance.new("TextLabel")
    NotifDesc.Size = UDim2.new(0, 180, 0, 16)
    NotifDesc.Position = UDim2.new(0, 58, 0, 32)
    NotifDesc.BackgroundTransparency = 1
    NotifDesc.Text = descText
    NotifDesc.TextColor3 = Color3.fromRGB(120, 140, 170)
    NotifDesc.Font = Enum.Font.Gotham
    NotifDesc.TextSize = 10
    NotifDesc.TextXAlignment = Enum.TextXAlignment.Left
    NotifDesc.Parent = NotifFrame

    TweenService:Create(NotifFrame, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Position = UDim2.new(1, -275, 1, -80)
    }):Play()

    task.delay(4, function()
        local slideOut = TweenService:Create(NotifFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
            Position = UDim2.new(1, 10, 1, -80)
        })
        slideOut:Play()
        slideOut.Completed:Wait()
        NotifFrame:Destroy()
    end)
end

