local ParticleContainer = Instance.new("Frame")
ParticleContainer.Name = "ParticleContainer"
ParticleContainer.Size = UDim2.new(1, 0, 1, 0)
ParticleContainer.BackgroundTransparency = 1
ParticleContainer.ClipsDescendants = true
ParticleContainer.ZIndex = 1
ParticleContainer.Parent = MainFrame

local function SpawnParticle()
    local pSize = math.random(3, 7)
    local startX = math.random(5, 95) / 100
    local Particle = Instance.new("Frame")
    Particle.Size = UDim2.new(0, pSize, 0, pSize)
    Particle.Position = UDim2.new(startX, 0, 1, 10)
    Particle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    Particle.BackgroundTransparency = math.random(20, 50) / 100
    Particle.BorderSizePixel = 0
    Particle.ZIndex = 1
    Particle.Parent = ParticleContainer

    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(1, 0)
    Corner.Parent = Particle

    local Glow = Instance.new("UIStroke")
    Glow.Color = Color3.fromRGB(180, 220, 255)
    Glow.Thickness = 1.5
    Glow.Transparency = 0.3
    Glow.Parent = Particle

    local duration = math.random(4, 7)
    local floatTween = TweenService:Create(Particle, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
        Position = UDim2.new(startX + (math.random(-10, 10) / 100), 0, 0, -20),
        BackgroundTransparency = 1
    })
    floatTween:Play()
    floatTween.Completed:Connect(function()
        Particle:Destroy()
    end)
end

task.spawn(function()
    while task.wait(0.3) do
        if MainFrame.Visible then
            SpawnParticle()
        end
    end
end)

-- ==================== 6. ระบบเปิด/ปิด UI ====================
local isOpen = true
local isAnimating = false

local function ToggleUI()
    if isAnimating then return end
    isAnimating = true

    TweenService:Create(ToggleBtn, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = UDim2.new(0, 42, 0, 42)}):Play()
    task.wait(0.1)
    TweenService:Create(ToggleBtn, TweenInfo.new(0.1, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Size = UDim2.new(0, 48, 0, 48)}):Play()

    if isOpen then
        local tweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In)
        local sizeTween = TweenService:Create(MainFrame, tweenInfo, {Size = ClosedSize, Position = ClosedPos})
        sizeTween:Play()
        sizeTween.Completed:Wait()
        MainFrame.Visible = false
        isOpen = false
    else
        MainFrame.Visible = true
        local tweenInfo = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        local sizeTween = TweenService:Create(MainFrame, tweenInfo, {Size = NormalSize, Position = NormalPos})
        sizeTween:Play()
        sizeTween.Completed:Wait()
        isOpen = true
    end

    isAnimating = false
end

ToggleBtn.MouseButton1Click:Connect(ToggleUI)

local function AddClickAnimation(btn)
    local originalSize = btn.Size
    btn.MouseButton1Down:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = originalSize - UDim2.new(0, 4, 0, 4)}):Play()
    end)
    btn.MouseButton1Up:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = originalSize}):Play()
    end)
    btn.MouseLeave:Connect(function()
        TweenService:Create(btn, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = originalSize}):Play()
    end)
end

