-- ==================== TAB SYSTEM ====================
local TabFrames = {}
local NavButtons = {}
local NavIcons = {}
local NavIndicators = {}

local function CreateNav(name, iconId, posY, active, tabKey)
    local Btn = Instance.new("TextButton")
    Btn.Size = UDim2.new(0.88, 0, 0, 36)
    Btn.Position = UDim2.new(0.06, 0, 0, posY)
    Btn.BackgroundColor3 = active and Color3.fromRGB(18, 28, 48) or Color3.fromRGB(7, 10, 16)
    Btn.BackgroundTransparency = active and 0 or 0.5
    Btn.Text = name
    Btn.TextColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(110, 125, 150)
    Btn.Font = Enum.Font.GothamMedium
    Btn.TextSize = 12
    Btn.TextXAlignment = Enum.TextXAlignment.Left
    Btn.BorderSizePixel = 0
    Btn.ZIndex = 3
    Btn.Parent = Sidebar

    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(0, 8)
    Corner.Parent = Btn

    local Padding = Instance.new("UIPadding")
    Padding.PaddingLeft = UDim.new(0, 38)
    Padding.Parent = Btn

    local Icon = Instance.new("ImageLabel")
    Icon.Size = UDim2.new(0, 16, 0, 16)
    Icon.Position = UDim2.new(0, -26, 0.5, -8)
    Icon.BackgroundTransparency = 1
    Icon.Image = iconId
    Icon.ImageColor3 = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(110, 125, 150)
    Icon.ZIndex = 3
    Icon.Parent = Btn

    local Indicator = nil
    if active then
        Indicator = Instance.new("Frame")
        Indicator.Size = UDim2.new(0, 3, 0, 18)
        Indicator.Position = UDim2.new(0, -32, 0.5, -9)
        Indicator.BackgroundColor3 = Color3.fromRGB(50, 140, 255)
        Indicator.BorderSizePixel = 0
        Indicator.ZIndex = 3
        Indicator.Parent = Btn

        local IndCorner = Instance.new("UICorner")
        IndCorner.CornerRadius = UDim.new(1, 0)
        IndCorner.Parent = Indicator
    end

    AddClickAnimation(Btn)

    NavButtons[tabKey] = Btn
    NavIcons[tabKey] = Icon
    NavIndicators[tabKey] = Indicator

    return Btn
end

local function SetActiveTab(tabKey)
    for key, btn in pairs(NavButtons) do
        local isActive = (key == tabKey)
        btn.BackgroundColor3 = isActive and Color3.fromRGB(18, 28, 48) or Color3.fromRGB(7, 10, 16)
        btn.BackgroundTransparency = isActive and 0 or 0.5
        btn.TextColor3 = isActive and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(110, 125, 150)
        if NavIcons[key] then
            NavIcons[key].ImageColor3 = isActive and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(110, 125, 150)
        end
        if NavIndicators[key] then
            NavIndicators[key]:Destroy()
            NavIndicators[key] = nil
        end
        if isActive then
            local Indicator = Instance.new("Frame")
            Indicator.Size = UDim2.new(0, 3, 0, 18)
            Indicator.Position = UDim2.new(0, -32, 0.5, -9)
            Indicator.BackgroundColor3 = Color3.fromRGB(50, 140, 255)
            Indicator.BorderSizePixel = 0
            Indicator.ZIndex = 3
            Indicator.Parent = btn
            local IndCorner = Instance.new("UICorner")
            IndCorner.CornerRadius = UDim.new(1, 0)
            IndCorner.Parent = Indicator
            NavIndicators[key] = Indicator
        end
    end
    for key, frame in pairs(TabFrames) do
        frame.Visible = (key == tabKey)
    end
    if HeaderTitle then
        local tabNames = {Home = "Home", Auto = "Auto", Plot = "Plot", ["Server Hop"] = "Server Hop", Player = "Player"}
        HeaderTitle.Text = "BLADE BALL x LUXION / " .. (tabNames[tabKey] or tabKey)
    end
end

