-- ==================== BLADE BALL UI MANAGER ====================
-- จัดการซ่อน/แสดง UI เดิมของ Blade Ball
local BladeBallGuis = {}
local bladeBallVisible = false

-- บันทึก GUI ที่มีอยู่ก่อนรัน Blade Ball
local existingGuis = {}
for _, gui in ipairs(PlayerGui:GetChildren()) do
    if gui:IsA("ScreenGui") then
        existingGuis[gui] = true
    end
end

local function RefreshBladeBallGuis()
    BladeBallGuis = {}
    for _, gui in ipairs(PlayerGui:GetChildren()) do
        if gui:IsA("ScreenGui") and gui.Name ~= "LuxionHubUI" and not existingGuis[gui] then
            table.insert(BladeBallGuis, gui)
        end
    end
end

local function SetBladeBallVisible(visible)
    RefreshBladeBallGuis()
    for _, gui in ipairs(BladeBallGuis) do
        gui.Enabled = visible
    end
    bladeBallVisible = visible
end

-- ปุ่มเปิด/ปิดเมนู Blade Ball เดิม (ใช้ในทุกแท็บ)
local function CreateBladeBallToggleBtn(parent, posY)
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(0.8, 0, 0, 36)
    btn.Position = UDim2.new(0.1, 0, 0, posY)
    btn.BackgroundColor3 = Color3.fromRGB(30, 60, 120)
    btn.Text = "Open Blade Ball Menu"
    btn.TextColor3 = Color3.fromRGB(255, 255, 255)
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 13
    btn.BorderSizePixel = 0
    btn.ZIndex = 3
    btn.Parent = parent

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = btn

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(50, 140, 255)
    stroke.Thickness = 1.5
    stroke.Parent = btn

    AddClickAnimation(btn)

    btn.MouseButton1Click:Connect(function()
        bladeBallVisible = not bladeBallVisible
        SetBladeBallVisible(bladeBallVisible)
        if bladeBallVisible then
            btn.Text = "Close Blade Ball Menu"
            btn.BackgroundColor3 = Color3.fromRGB(120, 40, 40)
            ShowNotification("BLADE BALL", "เปิดเมนู Blade Ball แล้ว")
        else
            btn.Text = "Open Blade Ball Menu"
            btn.BackgroundColor3 = Color3.fromRGB(30, 60, 120)
            ShowNotification("BLADE BALL", "ซ่อนเมนู Blade Ball แล้ว")
        end
    end)

    return btn
end

-- ==================== TAB CONTENT FRAMES ====================
local function CreateTabFrame(tabKey)
    local frame = Instance.new("ScrollingFrame")
    frame.Size = UDim2.new(1, -15, 1, -50)
    frame.Position = UDim2.new(0, 10, 0, 48)
    frame.BackgroundTransparency = 1
    frame.BorderSizePixel = 0
    frame.CanvasSize = UDim2.new(0, 0, 0, 600)
    frame.ScrollBarThickness = 3
    frame.ZIndex = 2
    frame.Visible = (tabKey == "Home")
    frame.Parent = Content
    TabFrames[tabKey] = frame
    return frame
end

