local function RefreshPlayerList()
    for _, child in ipairs(PlayerScroll:GetChildren()) do
        if child:IsA("TextLabel") then child:Destroy() end
    end
    PlayerTitle.Text = "Player List (" .. #Players:GetPlayers() .. ")"
    local y = 0
    for _, p in ipairs(Players:GetPlayers()) do
        local label = Instance.new("TextLabel")
        label.Size = UDim2.new(1, 0, 0, 22)
        label.BackgroundColor3 = Color3.fromRGB(22, 32, 55)
        label.BackgroundTransparency = 0.3
        label.Text = "  " .. p.Name .. (p == LocalPlayer and " (You)" or "")
        label.TextColor3 = p == LocalPlayer and Color3.fromRGB(80, 160, 255) or Color3.fromRGB(200, 210, 230)
        label.Font = Enum.Font.Gotham
        label.TextSize = 11
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.BorderSizePixel = 0
        label.ZIndex = 3
        label.Parent = PlayerScroll
        local lc = Instance.new("UICorner")
        lc.CornerRadius = UDim.new(0, 4)
        lc.Parent = label
        y = y + 26
    end
    PlayerScroll.CanvasSize = UDim2.new(0, 0, 0, y)
end

RefreshPlayerList()
Players.PlayerAdded:Connect(RefreshPlayerList)
Players.PlayerRemoving:Connect(RefreshPlayerList)

CreateBladeBallToggleBtn(PlayerTab, 185)

-- ==================== LIVE DATA UPDATER ====================
task.spawn(function()
    pcall(function()
        local info = MarketService:GetProductInfo(game.PlaceId)
        GTitle.Text = info.Name
        SideDesc.Text = info.Name
        HeaderTitle.Text = "BLADE BALL x LUXION / Home"
        GSub.Text = "by " .. info.Creator.Name
        GIcon.Image = "rbxassetid://" .. info.IconImageAssetId
    end)

    -- โหลด Progress Bar
    for i = 1, 100 do
        BarFill.Size = UDim2.new(i / 100, 0, 1, 0)
        LoadStatus.Text = "กำลังโหลดส่วนประกอบ... " .. i .. "%"
        task.wait(0.015)
    end
    task.wait(0.2)

    if setclipboard then
        pcall(function() setclipboard(DISCORD_LINK) end)
    end

    local loadFade = TweenService:Create(LoadFrame, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.In), {
        Size = UDim2.new(0, 0, 0, 0),
        Position = UDim2.new(0.5, 0, 0.5, 0)
    })
    loadFade:Play()
    loadFade.Completed:Wait()
    LoadFrame:Destroy()
    MainFrame.Visible = true
    ToggleBtn.Visible = true

    ShowNotification("BLADE BALL x LUXION", "โหลดเสร็จสิ้น! UI Luxion พร้อมใช้งาน")

    -- ซ่อน UI เดิมของ Blade Ball หลังจากรันแล้ว (รอ 5 วินาทีให้ Blade Ball โหลดเสร็จ)
    task.delay(5, function()
        RefreshBladeBallGuis()
        if #BladeBallGuis > 0 then
            SetBladeBallVisible(false)
            ShowNotification("BLADE BALL", "พบเมนู Blade Ball เดิม ถูกซ่อนไว้แล้ว\nกดปุ่ม Open Blade Ball Menu เพื่อเปิด")
        end
    end)

    -- ตรวจจับ GUI ใหม่ที่สร้างขึ้นหลังจากนี้ (กรณี Blade Ball โหลดช้า)
    PlayerGui.ChildAdded:Connect(function(child)
        if child:IsA("ScreenGui") and child.Name ~= "LuxionHubUI" and not existingGuis[child] then
            task.wait(0.5)
            if not bladeBallVisible then
                pcall(function() child.Enabled = false end)
            end
        end
    end)

    local friendCount = 0
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer and LocalPlayer:IsFriendsWith(p.UserId) then
            friendCount = friendCount + 1
        end
    end
    StatLabels["Friends"].Text = tostring(friendCount)
    StatLabels["Execs"].Text = "1"

    local startTime = tick()
    local lastTime = tick()
    local frameCount = 0
    RunService.RenderStepped:Connect(function()
        frameCount = frameCount + 1
        local currentTime = tick()
        if currentTime - lastTime >= 1 then
            local fps = math.floor(frameCount / (currentTime - lastTime))
            StatLabels["FPS"].Text = tostring(fps)
            frameCount = 0
            lastTime = currentTime
            local ping = math.floor(StatsService.Network.ServerStatsItem["Data Ping"]:GetValue())
            StatLabels["Ping"].Text = tostring(ping) .. "ms"
            StatLabels["Players"].Text = tostring(#Players:GetPlayers()) .. "/" .. tostring(Players.MaxPlayers)
            local sessionDuration = math.floor(currentTime - startTime)
            local mins = math.floor(sessionDuration / 60)
            local secs = sessionDuration % 60
            StatLabels["Session"].Text = string.format("%dm %ds", mins, secs)
        end
    end)
end)

